import{St as e,at as t,it as n,ot as r,st as i,t as a,tt as o,vt as s}from"./chunks/framework.B8HA7oqK.js";var c=JSON.parse(`{"title":"Browser Dialer","description":"","frontmatter":{},"headers":[],"relativePath":"en/config/features/browser_dialer.md","filePath":"en/config/features/browser_dialer.md","lastUpdated":1769206051000}`),l={name:`en/config/features/browser_dialer.md`};function u(a,c,l,u,d,f){let p=e(`Badge`);return s(),n(`div`,null,[c[0]||=t(`<h1 id="browser-dialer" tabindex="-1">Browser Dialer <a class="header-anchor" href="#browser-dialer" aria-label="Permalink to “Browser Dialer”">​</a></h1><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>Through uTLS, Xray can simulate the TLS handshake fingerprints of mainstream browsers (see the <code>fingerprint</code> option in TLS for details). However, it still cannot guarantee that the simulated browser behavior is perfectly consistent with a real browser at all times.</p><p>In response to this, the <a href="https://github.com/v2ray/discussion/issues/754#issuecomment-647934994" target="_blank" rel="noreferrer">Browser Dialer</a> was created. Users open a page at <code>localhost:8080</code> in their own browser. This page uses native JS to act as Xray&#39;s network stack, establishing TLS and HTTP connections with the proxy server.</p><p>This method concisely implements real browser TLS fingerprints and behavioral characteristics, providing maximum anti-detection and anti-blocking capabilities.</p><p>However, the current Browser Dialer has the following drawbacks:</p><ul><li>Users need to manually open the browser.</li><li>Connections initiated by the browser must be direct. Users using <code>tun</code> need to pay special attention to avoid creating infinite routing loops.</li><li>The browser can only initiate HTTP connections, so currently, only <a href="./../transports/websocket.html">WebSocket</a> and <a href="https://github.com/XTLS/Xray-core/discussions/4113" target="_blank" rel="noreferrer">XHTTP</a> transport methods are supported.</li><li>When the browser connects from the <code>localhost:8080</code> page to the proxy server, <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a> needs to be considered.</li><li>Since data is processed via JS, there will be some performance overhead.</li><li>Custom SNI or Host cannot be used; that is, <code>SNI == host == address</code>. Custom HTTP headers and other <code>tlsSettings</code> items will be ignored.</li></ul><h2 id="configuration-method" tabindex="-1">Configuration Method <a class="header-anchor" href="#configuration-method" aria-label="Permalink to “Configuration Method”">​</a></h2><ol><li>Prepare a WebSocket or XHTTP configuration. Note that the <code>address</code> must be a domain name. If you need to specify an IP, please configure DNS or the system <code>hosts</code> file.</li><li>Start Xray using the environment variable <code>XRAY_BROWSER_DIALER=127.0.0.1:8080</code>. <ul><li>On Windows: <code>set XRAY_BROWSER_DIALER=127.0.0.1:8080</code></li><li>On Linux: <code>XRAY_BROWSER_DIALER=127.0.0.1:8080 ./xray -c config.json</code></li></ul></li><li>Ensure the browser connects directly (or configure the routing so that the server address is sent directly via <code>freedom</code>). Open the page <code>localhost:8080</code>. You can also use <code>F12</code> to check <code>Console</code> and <code>Network</code>.</li><li>Browsers limit the number of outbound connections, so it is recommended to enable <code>Mux.Cool</code>.</li></ol><h2 id="internal-communication-mechanism" tabindex="-1">Internal Communication Mechanism <a class="header-anchor" href="#internal-communication-mechanism" aria-label="Permalink to “Internal Communication Mechanism”">​</a></h2><ul><li>Xray listens on the address/port <code>http://127.0.0.1:8080</code> as an HTTP server. The browser visits this address and loads the JS in the webpage.</li><li>The JS actively establishes a WebSocket connection to <code>http://127.0.0.1:8080</code>. Upon success, Xray sends the connection to a channel.</li><li>When a connection needs to be established, Xray retrieves an available connection from the channel and sends the target URL and optional early data.</li><li>After the JS successfully connects to the target, it notifies Xray and continues to use this connection to forward data in full-duplex mode. Connection closure is synchronized.</li><li>The connection is closed after use, but the JS ensures that new idle connections are always available.</li></ul><h2 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to “WebSocket”">​</a></h2>`,12),i(p,{text:`v1.4.1+`,type:`warning`}),c[1]||=t(`<p>Based on browser requirements, the following adjustments were made to the early data mechanism:</p><ul><li>The server response header will carry the requested <code>Sec-WebSocket-Protocol</code>, which preliminarily obfuscates the length characteristics of the WSS handshake response.</li><li>The early data encoding used for browsers is <code>base64.RawURLEncoding</code> instead of <code>StdEncoding</code>. The server has made compatibility adjustments.</li><li>Additionally, due to <a href="https://github.com/XTLS/Xray-core/pull/375" target="_blank" rel="noreferrer">Xray-core#375</a> recommending <code>?ed=2048</code>, this PR also expanded a <code>MaxHeaderBytes</code> limit on the server side to 4096. ~~ (Although it seems fine without changing it) ~~</li></ul><h2 id="xhttp" tabindex="-1">XHTTP <a class="header-anchor" href="#xhttp" aria-label="Permalink to “XHTTP”">​</a></h2>`,3),i(p,{text:`v1.8.19+`,type:`warning`}),c[2]||=o(`p`,null,[o(`a`,{href:`https://github.com/XTLS/Xray-core/discussions/4113`,target:`_blank`,rel:`noreferrer`},`XHTTP`),r(` itself supports QUIC. If you want to use the browser's own QUIC network stack, Chrome users can configure it in `),o(`code`,null,`chrome://flags`),r(`. Other browsers also have relevant options.`)],-1),c[3]||=o(`p`,null,[r(`In principle, `),o(`code`,null,`tlsSettings`),r(` items will be ignored, and the HTTP version used will be determined entirely by the browser.`)],-1)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};